/**
 * Brand asset for the browser half.
 *
 * One simplified logo serves both themes (grays + the DeepSeek whale read
 * well on light and dark backgrounds); the same file is the site favicon
 * (dsh-plugins-mp.com/apps/web/public/logo-omg.svg). Embedded as a base64
 * data URI — the client bundle is a single self-contained CJS closure with
 * no asset serving, so file URLs are not an option.
 */
import type { ReactNode } from 'react'

const LOGO = 'data:image/svg+xml;base64,'

/** The marketplace mark at the given pixel size; theme-independent. */
export function BrandMark(props: { size: number }): ReactNode {
  return (
    <img
      src={LOGO}
      width={props.size}
      height={props.size}
      alt=""
      aria-hidden="true"
      style={{
        width: props.size,
        height: props.size,
        display: 'inline-block',
        verticalAlign: 'middle',
        flex: '0 0 auto',
      }}
    />
  )
}
